import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Sharing & export","description":"Share a session as a web page, automate sharing with share:auto, take links back down with /unshare, and move sessions with export/import.","frontmatter":{"title":"Sharing & export","description":"Share a session as a web page, automate sharing with share:auto, take links back down with /unshare, and move sessions with export/import."},"headers":[],"relativePath":"using/sharing.md","filePath":"using/sharing.md"}'),o={name:"using/sharing.md"};function n(r,s,h,l,p,d){return a(),i("div",null,[...s[0]||(s[0]=[t(`<p>Sometimes the most useful thing an agent produced is the story of how it worked. Sharing publishes that story — and this page is honest about what that means.</p><h2 id="manual-sharing" tabindex="-1">Manual sharing <a class="header-anchor" href="#manual-sharing" aria-label="Permalink to &quot;Manual sharing&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/share      # in the TUI → creates the link, copies it to your clipboard</span></span>
<span class="line"><span>/unshare    # deletes it; the link stops working immediately</span></span></code></pre></div><p>The first time you share in a session group, PrioriCode shows a consent prompt explaining what leaves your machine. Read it — it&#39;s the one screen where you decide what a share is.</p><p>A share is a <strong>read-only transcript page</strong>: messages, tool calls, diffs, rendered by the hosted share service. The default backend is <code>https://opncd.ai</code>; point it at your own deployment with the <code>enterprise.url</code> config (self-hostable — see <a href="./../platforms/enterprise.html">enterprise</a>). Share URLs look like <code>https://&lt;host&gt;/share/&lt;slug&gt;</code>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Assume every share is public and permanent-until-deleted. Transcripts contain your prompts and file contents the agent read. If secrets were in context, they&#39;re in the page. <code>/unshare</code> is the undo; <code>PRIORICODE_DISABLE_SHARE=1</code> is the insurance policy; <code>&quot;share&quot;: &quot;disabled&quot;</code> in config removes <code>/share</code> from the TUI entirely.</p></div><h2 id="automatic-sharing" tabindex="-1">Automatic sharing <a class="header-anchor" href="#automatic-sharing" aria-label="Permalink to &quot;Automatic sharing&quot;">​</a></h2><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// prioricode.json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;share&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>&quot;manual&quot;</code> (default)</td><td>Links exist only when you <code>/share</code>.</td></tr><tr><td><code>&quot;auto&quot;</code></td><td>Every session gets shared as it runs — for teams who review sessions openly.</td></tr><tr><td><code>&quot;disabled&quot;</code></td><td>No sharing anywhere: TUI entry hidden, server routes off.</td></tr></tbody></table><p>Equivalent one-offs: the <code>PRIORICODE_AUTO_SHARE=1</code> env, <code>autoshare: true</code> (legacy spelling of <code>share: auto</code>), and <code>prioricode run --share</code>.</p><p>Live updates: a shared session streams its ongoing changes to the page — your colleague watches the agent work, not just the result.</p><h2 id="export-import-sessions-as-files" tabindex="-1">Export &amp; import: sessions as files <a class="header-anchor" href="#export-import-sessions-as-files" aria-label="Permalink to &quot;Export &amp; import: sessions as files&quot;">​</a></h2><p>Sharing is for eyeballs; export/import is for machines and archives.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # pick a session interactively</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ses_…</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # or grab a specific one</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sanitize</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ses_…</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # redact transcript + file data for bug reports</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # back into a local session</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://opncd.ai/share/abc123</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or straight from a share link</span></span></code></pre></div><p>The export is the full record — session, messages, parts, todos. <code>--sanitize</code> replaces sensitive payloads with <code>[redacted:kind:id]</code> markers so you can attach an export to an issue without turning it into a data leak. Importing a sanitized export keeps the structure; the agent just can&#39;t see what you redacted.</p><p>For CI archaeology: <code>prioricode session list --format json</code> gives IDs programmatically, <code>run --session &lt;id&gt; --continue</code> resumes them, and <code>stats</code> tallies them. See <a href="./headless.html">headless</a>.</p><h2 id="what-sharing-is-not" tabindex="-1">What sharing is not <a class="header-anchor" href="#what-sharing-is-not" aria-label="Permalink to &quot;What sharing is not&quot;">​</a></h2><ul><li>Not a sync mechanism — for two machines, use the <a href="./../platforms/server.html">server</a>.</li><li>Not collaboration — viewers can&#39;t reply or steer; the page is a recording.</li><li>Not scoped to a subset — you share the whole session, not a message. Copy what you need (<code>/copy</code>) for smaller pieces.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./sessions.html">Sessions</a> — The thing being shared. <ul><li><a href="./../support/troubleshooting.html">Security model</a> — Threat model and hardening notes.</li><li><a href="./../platforms/enterprise.html">Enterprise</a> — Self-hosting share pages.</li><li><a href="./../reference/config.html">Config reference</a> — <code>share</code>, <code>enterprise.url</code>, and friends.</li></ul></li></ul>`,20)])])}const g=e(o,[["render",n]]);export{u as __pageData,g as default};
